using System.Globalization;
using DlnRenderer.Core.Models;
using DlnRenderer.Player.Mpv;
using Xunit.Abstractions;

namespace DlnRenderer.Player.Tests;

/// <summary>
/// Stage D (D1/D3): measures what the engine actually plays, instead of trusting the protocol
/// declaration.
/// </summary>
/// <remarks>
/// <para>
/// The fixtures are generated by <c>tools/media-compat/make-fixtures.ps1</c> and are not committed;
/// without them every test here skips with an instruction rather than passing silently.
/// </para>
/// <para>
/// Each measured sample appends one pipe-separated row to the file named by
/// <c>DLNR_MEDIA_RESULTS</c> (unset = no recording), which
/// <c>tools/media-compat/measure-media.ps1</c> turns into <c>docs/media-matrix.md</c>. The assertions
/// still fail the run, so a newly unplayable format cannot quietly become a line in the matrix.
/// </para>
/// </remarks>
public sealed class MediaCompatibilityTests
{
    private static readonly TimeSpan LoadTimeout = TimeSpan.FromSeconds(30);

    private readonly ITestOutputHelper _output;

    public MediaCompatibilityTests(ITestOutputHelper output) => _output = output;

    private static string? FixtureDirectory => Environment.GetEnvironmentVariable("DLNR_MEDIA_FIXTURES");

    private static string? ResultsPath => Environment.GetEnvironmentVariable("DLNR_MEDIA_RESULTS");

    /// <summary>
    /// Plays every fixture and asserts the outcome the file name promises: real media must play,
    /// <c>invalid-*</c> (not media) and <c>unsupported-*</c> (real media with no decoder) must fail.
    /// A format that stops decoding shows up as a failing test, not as a silent row in a document.
    /// </summary>
    [MpvFact]
    public async Task Every_generated_fixture_has_the_outcome_its_name_promises()
    {
        var directory = FixtureDirectory;
        if (string.IsNullOrWhiteSpace(directory) || !Directory.Exists(directory))
        {
            // Not a failure: the fixtures are generated, not committed. The reason is written both
            // to the test output and to the results file, so a matrix built from an empty run says
            // "nothing measured" instead of looking like "everything passed".
            var reason =
                $"no fixture directory at '{directory}'; run " +
                "pwsh tools/media-compat/make-fixtures.ps1 (measure-media.ps1 does it for you)";
            _output.WriteLine(reason);
            Record(FixtureRow.For("# fixtures-missing", string.Empty, null, played: false, detail: reason));
            return;
        }

        var fixtures = Directory
            .EnumerateFiles(directory)
            .Where(path => !path.EndsWith(".srt", StringComparison.OrdinalIgnoreCase))
            .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
            .ToList();

        Assert.NotEmpty(fixtures);

        var failures = new List<string>();
        foreach (var fixture in fixtures)
        {
            var outcome = await MeasureAsync(fixture).ConfigureAwait(false);
            Record(outcome);

            // "invalid-*" (not media at all) and "unsupported-*" (a format the sink list used to
            // claim) must fail; anything else failing means a real format stopped decoding, and
            // anything in those two groups playing means a declaration was removed wrongly.
            var name = Path.GetFileName(fixture);
            var shouldBePlayable = !IsExpectedToFail(name);
            if (shouldBePlayable && !outcome.Played)
            {
                failures.Add($"{name}: {outcome.Detail}");
            }
            else if (!shouldBePlayable && outcome.Played)
            {
                failures.Add($"{name}: played, but the file name says it must not");
            }
        }

        Assert.True(
            failures.Count == 0,
            "compatibility failures:" + Environment.NewLine + string.Join(Environment.NewLine, failures));
    }

    /// <summary>D3: on a machine that has a decoder, auto-safe must actually use it.</summary>
    [MpvFact]
    public async Task Hardware_decoding_is_used_when_the_machine_supports_it()
    {
        var fixture = Path.Combine(AppContext.BaseDirectory, "Media", "sample-video.mp4");
        Assert.True(File.Exists(fixture), $"missing fixture: {fixture}");

        await using var player = CreatePlayer(hardwareDecoding: true);
        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(60));

        await player.LoadAsync(new MediaInfo(new Uri(fixture)), timeout.Token);
        await WaitForAsync(player, s => s.State == PlaybackState.Paused, "loaded").ConfigureAwait(false);
        await player.PlayAsync(timeout.Token);
        await WaitForAsync(
            player,
            s => s.State == PlaybackState.Playing && s.Position > TimeSpan.FromMilliseconds(300),
            "playing").ConfigureAwait(false);

        var method = player.CurrentHardwareDecodingMethod;
        Record(FixtureRow.For("hwdec-auto-safe-sample-video", "Video", method, played: true, detail: method ?? "software"));

        Assert.True(
            !string.IsNullOrWhiteSpace(method),
            "mpv reported no hardware decoding method; auto-safe was expected to pick one on this machine.");
    }

    /// <summary>
    /// D3: asking for a decoder the machine does not have must fall back to software, not fail the
    /// file. <c>vaapi</c> is a machine-independent choice: it does not exist on Windows.
    /// </summary>
    [MpvFact]
    public async Task An_unavailable_hardware_decoding_method_falls_back_to_software()
    {
        var fixture = Path.Combine(AppContext.BaseDirectory, "Media", "sample-video.mp4");
        Assert.True(File.Exists(fixture), $"missing fixture: {fixture}");

        await using var player = new MpvPlayer(new MpvPlayerOptions
        {
            AudioOutput = "null",
            VideoOutput = "null",
            HardwareDecodingMethod = "vaapi",
            PositionUpdateInterval = TimeSpan.FromMilliseconds(100),
        });

        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(60));

        await player.LoadAsync(new MediaInfo(new Uri(fixture)), timeout.Token);
        await WaitForAsync(player, s => s.State == PlaybackState.Paused, "loaded with vaapi requested").ConfigureAwait(false);
        await player.PlayAsync(timeout.Token);

        var playing = await WaitForAsync(
            player,
            s => s.State == PlaybackState.Playing && s.Position > TimeSpan.FromMilliseconds(300),
            "playing after hardware decoding was unavailable").ConfigureAwait(false);

        Assert.Equal(PlaybackState.Playing, playing.State);
        Assert.True(
            player.CurrentHardwareDecodingMethod is null,
            "vaapi cannot exist on Windows, so the active method should be none (software), " +
            $"but mpv reported '{player.CurrentHardwareDecodingMethod}'.");
        Record(FixtureRow.For("hwdec-vaapi-fallback", "Video", player.CurrentHardwareDecodingMethod, played: true, detail: "fell back to software"));
    }

    /// <summary>File-name contract: <c>invalid-*</c> is not media, <c>unsupported-*</c> is real media the engine cannot decode.</summary>
    private static bool IsExpectedToFail(string name)
        => name.StartsWith("invalid-", StringComparison.OrdinalIgnoreCase)
            || name.StartsWith("unsupported-", StringComparison.OrdinalIgnoreCase);

    private static MpvPlayer CreatePlayer(bool hardwareDecoding = true) => new(new MpvPlayerOptions
    {
        AudioOutput = "null",
        VideoOutput = "null",
        HardwareDecoding = hardwareDecoding,
        PositionUpdateInterval = TimeSpan.FromMilliseconds(100),
    });

    /// <summary>Loads, plays and observes one fixture, returning what actually happened.</summary>
    private static async Task<FixtureRow> MeasureAsync(string fixture)
    {
        var name = Path.GetFileName(fixture);
        var expectedToPlay = !name.StartsWith("invalid-", StringComparison.OrdinalIgnoreCase);

        await using var player = CreatePlayer();
        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(90));

        try
        {
            await player.LoadAsync(new MediaInfo(new Uri(fixture)), timeout.Token).ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            return FixtureRow.For(name, string.Empty, null, played: false, detail: $"load rejected: {ex.Message}");
        }

        PlaybackStatus status;
        try
        {
            status = await WaitForAsync(
                player,
                s => s.State is PlaybackState.Paused or PlaybackState.Error,
                "load finished").ConfigureAwait(false);
        }
        catch (TimeoutException ex)
        {
            return FixtureRow.For(name, string.Empty, null, played: false, detail: $"timeout: {ex.Message}");
        }

        if (status.State == PlaybackState.Error)
        {
            return FixtureRow.For(name, string.Empty, null, played: false, detail: status.ErrorMessage ?? "unknown error");
        }

        var duration = status.Duration?.TotalSeconds;
        var kind = status.MediaKind.ToString();

        try
        {
            await player.PlayAsync(timeout.Token).ConfigureAwait(false);
            status = await WaitForAsync(
                player,
                s => s.State == PlaybackState.Playing && s.Position > TimeSpan.FromMilliseconds(300),
                "position advancing").ConfigureAwait(false);
        }
        catch (TimeoutException ex)
        {
            return FixtureRow.For(name, kind, null, played: false, detail: $"loaded, but never advanced: {ex.Message}", duration);
        }

        return FixtureRow.For(
            name,
            kind,
            player.CurrentHardwareDecodingMethod,
            played: true,
            detail: string.Empty,
            duration);
    }

    private static void Record(FixtureRow row)
    {
        var path = ResultsPath;
        if (string.IsNullOrWhiteSpace(path))
        {
            return;
        }

        var directory = Path.GetDirectoryName(path);
        if (!string.IsNullOrEmpty(directory))
        {
            Directory.CreateDirectory(directory);
        }

        File.AppendAllText(path, row.ToLine() + Environment.NewLine);
    }

    private static async Task<PlaybackStatus> WaitForAsync(
        MpvPlayer player,
        Func<PlaybackStatus, bool> predicate,
        string description)
    {
        var deadline = DateTime.UtcNow + LoadTimeout;
        var last = PlaybackStatus.Empty;

        while (DateTime.UtcNow < deadline)
        {
            last = await player.GetStatusAsync(CancellationToken.None).ConfigureAwait(false);
            if (predicate(last))
            {
                return last;
            }

            await Task.Delay(50).ConfigureAwait(false);
        }

        throw new TimeoutException(
            $"'{description}' after {LoadTimeout}. state={last.State}, kind={last.MediaKind}, " +
            $"position={last.Position}, duration={last.Duration}, error={last.ErrorMessage ?? "<none>"}");
    }
}

/// <summary>One measured fixture, serialised for <c>measure-media.ps1</c> to turn into the matrix.</summary>
internal sealed record FixtureRow(string File, string Kind, string Hwdec, bool Played, string Detail, double? Duration)
{
    public static FixtureRow For(string file, string kind, string? hwdec, bool played, string detail, double? duration = null)
        => new(
            Path.GetFileName(file),
            kind,
            hwdec ?? "software",
            played,
            detail.Replace('|', '/').Replace('\n', ' ').Replace('\r', ' '),
            duration);

    public string ToLine() => string.Join(
        '|',
        File,
        Kind,
        Duration is { } seconds
            ? seconds.ToString("0.00", CultureInfo.InvariantCulture)
            : string.Empty,
        Hwdec,
        Played ? "played" : "failed",
        Detail);
}
